<script>
 import {formatDate} from '$lib/date.js';
 import {onMount} from 'svelte';
 import {page} from '$app/stores';
 import {locale} from '$lib/i18n.js';
 import {listLogs,listAuditLogs,listProjects,listDevices} from '$lib/api.js';
 import {notify} from '$lib/stores.js';
 import Button from '$lib/components/Button.svelte';
 let logs=[],auditLogs=[],projects=[],devices=[],loading=true,limit=100,search='',typeFilter='all',deviceFilter='all',projectFilter='all',rangeFilter='all',levelFilter='all',selected=null;
 $: ru=$locale!=='en';
 $: filtered=logs.filter(log=>{const q=search.trim().toLowerCase();if(q&&!JSON.stringify(log).toLowerCase().includes(q))return false;if(typeFilter!=='all'&&eventType(log)!==typeFilter)return false;if(levelFilter!=='all'&&level(log)!==levelFilter)return false;if(deviceFilter!=='all'&&(log.device||'')!==deviceFilter)return false;if(projectFilter!=='all'&&!JSON.stringify(log).includes(projectFilter))return false;if(rangeFilter!=='all'){const age=Date.now()-new Date(log.created_at).getTime();const max=rangeFilter==='24h'?86400000:rangeFilter==='7d'?604800000:2592000000;if(!Number.isFinite(age)||age>max)return false}return true});
 async function load(){loading=true;const projectId=$page.url.searchParams.get('project_id')||'';const [r,a,p,d]=await Promise.all([listLogs(limit,projectId),listAuditLogs(limit,projectId),listProjects(),listDevices()]);if(r.ok)logs=r.data.logs||[];else notify(r.error||'Could not load logs','error');if(a.ok)auditLogs=a.data.audit_logs||[];else auditLogs=[];if(p.ok)projects=p.data.projects||[];if(d.ok)devices=d.data.devices||[];loading=false}
 onMount(load);
 function details(value){if(!value)return '—';if(typeof value==='string')return value;return Object.entries(value).map(([k,v])=>k+': '+String(v)).join(' · ')}
 function eventType(log){const a=String(log.action||'').toLowerCase();if(a.includes('deploy')||a.includes('build')||a.includes('rollback'))return 'deployment';if(a.includes('agent')||a.includes('device')||log.device)return 'agent';if(a.includes('project')||a.includes('site'))return 'project';if(a.includes('login')||a.includes('password')||a.includes('token')||a.includes('integration')||a.includes('security'))return 'security';return 'system'}
 function level(log){const a=String(log.action||'').toLowerCase();if(log.details?.error||a.includes('failed')||a.includes('error'))return 'error';if(a.includes('completed')||a.includes('connected')||a.includes('created')||a.includes('success'))return 'success';if(a.includes('warning')||a.includes('denied'))return 'warning';return 'info'}
 function typeLabel(type){return ({system:ru?'Система':'System',agent:ru?'Agent':'Agent',deployment:ru?'Развёртывание':'Deployment',project:ru?'Проект':'Project',security:ru?'Безопасность':'Security'})[type]||type}
 function levelLabel(value){return ({info:'Info',success:ru?'Успех':'Success',warning:ru?'Предупреждение':'Warning',error:ru?'Ошибка':'Error'})[value]||value}
 function exportCSV(){const rows=[['Timestamp','Type','Source','Event','Level'],...filtered.map(log=>[log.created_at,eventType(log),log.device||'',log.action||'',level(log)])];const csv=rows.map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='yevqo-logs.csv';a.click();URL.revokeObjectURL(url)}
 async function copyDetails(){try{await navigator.clipboard.writeText(JSON.stringify(selected,null,2));notify(ru?'Данные скопированы':'Details copied','success')}catch{notify(ru?'Не удалось скопировать':'Could not copy details','error')}}
</script>
<svelte:head><title>{ru?'Журналы':'Logs'} · Yevqo</title></svelte:head>
<div class="page-header"><div><div class="eyebrow">OPERATIONS / AUDIT</div><h1 class="page-title">{ru?'Журналы':'Logs'}</h1><p class="page-desc">{ru?'События и операции во всей инфраструктуре.':'Track events and operations across your infrastructure.'}</p></div><div class="header-actions"><Button on:click={load}>↻ {ru?'Обновить':'Refresh'}</Button><Button variant="primary" on:click={exportCSV} disabled={!filtered.length}>{ru?'Экспорт CSV':'Export CSV'}</Button></div></div>
<div class="toolbar"><input class="input search" bind:value={search} placeholder={ru?'Поиск по журналам…':'Search logs…'}/><select class="input" bind:value={typeFilter}><option value="all">{ru?'Все типы':'All types'}</option><option value="system">System</option><option value="agent">Agent</option><option value="deployment">Deployment</option><option value="project">Project</option><option value="security">Security</option></select><select class="input" bind:value={limit} on:change={load}><option value="50">50</option><option value="100">100</option><option value="200">200</option></select></div>
{#if loading}<div class="empty">{ru?'Загрузка журналов…':'Loading logs…'}</div>{:else if !filtered.length}<div class="empty">{ru?'Событий не найдено.':'No events found.'}</div>{:else}
<div class="log-table"><div class="log-head"><span>{ru?'Время':'Timestamp'}</span><span>{ru?'Тип':'Type'}</span><span>{ru?'Источник':'Source'}</span><span>{ru?'Событие':'Event'}</span><span>{ru?'Уровень':'Level'}</span></div>
{#each filtered as log (log.id)}<button class="log-row" on:click={()=>selected=log}><time>{log.created_at?formatDate(log.created_at):'—'}</time><span class="type-chip">{typeLabel(eventType(log))}</span><span class="source">{log.device||'Control Plane'}</span><strong>{String(log.action||'event').replaceAll('_',' ')}</strong><span class={'level '+level(log)}>{levelLabel(level(log))}</span></button>{/each}</div>
{/if}
<section class="audit-section"><div class="section-heading"><h2>{ru?'Аудит безопасности':'Security audit'}</h2><span>{auditLogs.length} {ru?'событий':'events'}</span></div>
{#if !auditLogs.length}<div class="empty audit-empty">{ru?'Нет доступных событий аудита или роль не разрешает просмотр.':'No audit events available or your role cannot view them.'}</div>{:else}
<div class="audit-list">{#each auditLogs as event (event.id)}<article class="audit-row"><span class="audit-mark">⌁</span><div><strong>{String(event.action||'event').replaceAll('_',' ')} · {event.outcome}</strong><small>{event.target_type}:{event.target_id} · actor #{event.actor_user_id||'system'} · {event.ip||'IP unknown'}</small></div><time>{formatDate(event.created_at)}</time></article>{/each}</div>{/if}</section>
{#if selected}<div class="details-backdrop" on:click={()=>selected=null}><section class="details-panel" on:click|stopPropagation><div class="details-head"><div><h2>{ru?'Детали события':'Event details'}</h2><small>{selected.id}</small></div><button on:click={()=>selected=null}>×</button></div><div class="detail-row"><span>{ru?'Время':'Timestamp'}</span><strong>{selected.created_at?formatDate(selected.created_at):'—'}</strong></div><div class="detail-row"><span>{ru?'Тип':'Type'}</span><strong>{typeLabel(eventType(selected))}</strong></div><div class="detail-row"><span>{ru?'Источник':'Source'}</span><strong>{selected.device||'Control Plane'}</strong></div><div class="detail-row"><span>{ru?'Уровень':'Level'}</span><strong>{levelLabel(level(selected))}</strong></div><pre>{JSON.stringify(selected.details||{},null,2)}</pre><Button on:click={copyDetails}>{ru?'Копировать данные':'Copy details'}</Button></section></div>{/if}
<style>
.eyebrow{font-size:9px;letter-spacing:.14em;color:var(--accent);font-weight:700;margin-bottom:7px}.header-actions{display:flex;gap:7px}.toolbar{display:flex;gap:8px;margin-bottom:12px}.toolbar .search{flex:1}.toolbar select{width:auto;min-width:105px;max-width:150px}.log-table{border:1px solid var(--border);border-radius:9px;overflow:hidden;background:var(--bg-card)}.log-head,.log-row{display:grid;grid-template-columns:1.15fr .8fr 1fr 1.4fr .65fr;gap:12px;align-items:center;padding:10px 12px}.log-head{background:var(--bg-elevated);color:var(--text-muted);font-size:9px;text-transform:uppercase;letter-spacing:.07em}.log-row{width:100%;border:0;border-top:1px solid var(--border);background:transparent;color:var(--text-main);text-align:left}.log-row:hover{background:var(--bg-hover)}.log-row time,.source{font-size:9px;color:var(--text-muted);overflow-wrap:anywhere}.log-row strong{font-size:10px;text-transform:capitalize}.type-chip,.level{font-size:9px;color:var(--text-muted)}.level.success{color:var(--accent)}.level.warning{color:var(--warning)}.level.error{color:var(--danger)}.audit-section{margin-top:25px}.section-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:9px}.section-heading h2{font-size:13px}.section-heading span{font-size:10px;color:var(--text-muted)}.audit-list{border:1px solid var(--border);border-radius:9px;background:var(--bg-card)}.audit-row{display:flex;align-items:center;gap:10px;padding:11px;border-bottom:1px solid var(--border)}.audit-row:last-child{border:0}.audit-mark{color:var(--accent)}.audit-row>div{display:grid;gap:3px;flex:1;min-width:0}.audit-row strong{font-size:10px}.audit-row small,.audit-row time{font-size:9px;color:var(--text-muted)}.details-backdrop{position:fixed;inset:0;z-index:70;display:flex;justify-content:flex-end;background:#0009}.details-panel{width:min(440px,100%);height:100%;overflow:auto;padding:18px;background:var(--bg-card);border-left:1px solid var(--border)}.details-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.details-head h2{font-size:14px}.details-head small{font-size:9px;color:var(--text-muted)}.details-head button{border:0;background:transparent;color:var(--text-main);font-size:20px}.detail-row{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid var(--border);font-size:10px}.detail-row span{color:var(--text-muted)}.detail-row strong{text-align:right;overflow-wrap:anywhere}.details-panel pre{padding:12px;margin:14px 0;border:1px solid var(--border);border-radius:7px;background:var(--bg-input);font:10px var(--mono);white-space:pre-wrap;overflow-wrap:anywhere}
@media(max-width:760px){.toolbar select{flex:1;max-width:none;min-width:0}.log-head{display:none}.log-row{grid-template-columns:1fr 1fr;gap:5px}.log-row strong{grid-column:1/-1}.source{display:none}.toolbar{flex-wrap:wrap}.toolbar .search{flex-basis:100%}.toolbar select{flex:1;min-width:0}.audit-row{align-items:flex-start;flex-wrap:wrap}.audit-row time{width:100%;margin-left:22px}.header-actions{flex-direction:column}}
</style>